from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
source=(ROOT/'work/dashboard_v5.html').read_text(encoding='utf-8')
source=source.replace('Hybrid lifecycle · version 5','Hybrid lifecycle · mentor update').replace('Hybrid 5.0','Mentor update 6.0').replace('28 October 2026','30 October 2026')
source=source.replace('<title>Talentra · Hybrid lifecycle</title>','<title>Talentra · Step 22 business scenarios</title>')
source=source.replace('<nav aria-label="Project views">','<nav aria-label="Project views"><button data-view="business">Business scenarios</button>')
panel='''<section class="panel" id="business"><div class="top"><div><div class="eyebrow">Step 22 · mentor business and functional scenarios</div><h1>Understand the hiring journey.</h1><p class="intro">The business meaning, user actions, data elements and KPIs are connected here. Counts come from a generated synthetic cohort. Conversion rates are proposed scenario inputs.</p></div><button class="button primary" id="mentoroutputs">Inspect step 22 and its Excel files</button></div>
<div class="metrics"><div class="metric featured"><label>Planning journeys</label><strong id="mpop"></strong><p>15,00,000 synthetic candidate-job pairs</p></div><div class="metric"><label>Submitted applications</label><strong id="mapps"></strong><p>Only the applied subset creates applications</p></div><div class="metric"><label>Onboarded</label><strong id="mhires"></strong><p>Joining confirmed, separate from offer acceptance</p></div><div class="metric"><label>Stage events generated</label><strong id="mevents"></strong><p>Saved files read back and reconciled</p></div></div>
<div class="notice"><b>Keep the meanings precise.</b> Screening before applying means pre-application eligibility. Employer rejection and candidate offer decline are different outcomes. Job family and engagement type are separate dimensions. Gig fulfilment belongs to the external system.</div>
<div class="split"><div class="card pad"><h2 style="margin-top:0">Hiring funnel</h2><div id="mfunnel"></div><div id="mbranches" class="muted small"></div></div><div class="card pad"><h2 style="margin-top:0">Gig workflow</h2><p>Worker profile and availability → worker application → requester acceptance or rejection → external handoff → provider status and earnings → requester rating after completion.</p><div id="mgig"></div><p class="muted small">Separate gig profiles and applications preserve window, price and ownership rules. The dataset does not implement an internal fulfilment engine.</p><h3>Source mapping</h3><p id="mmapping"></p><p class="muted small">Search attribution, job-scoped screening and assessment linkage gaps are explicitly proposed. They are not presented as existing physical columns.</p></div></div>
<h2>Job families and business context</h2><p class="muted">The mentor's delivery branch is retained under white-collar non-IT as a configurable business label. Blue-collar examples are proposed. These families can support permanent, contract or gig engagements.</p><div class="card scroll" id="mtaxonomy"></div>
<h2>Workflows for each actor</h2><div class="filters"><select id="mactor" aria-label="Workflow actor"></select></div><div class="card scroll" id="mworkflows"></div>
<h2>Business KPIs</h2><p class="muted small">Same-cohort denominators and calendar-day definitions are explicit. These are synthetic scenario results, not observed market conversion benchmarks.</p><div class="card scroll tablebox" id="mkpis"></div>
<h2>Scenario data and evidence</h2><p class="muted">The full files are in the ZIP. Excel uses aggregates and representative samples because the journey and event files exceed a single worksheet's row limit. Extract the complete ZIP to use the full-data file links.</p><div class="card scroll" id="mfiles"></div><div class="actions" style="margin-top:14px"><a class="button" href="scenario_data/generation_summary.json" download>Generation summary</a><a class="button" href="scenario_data/journey_sample.csv" download>Representative journey sample</a></div>
<h2>Native schema gaps and planned changes</h2><div class="card scroll" id="mgaps"></div><h2>Refusal cases</h2><div class="card scroll" id="mtests"></div></section>'''
source=source.replace('<section class="panel active" id="overview">',panel+'<section class="panel active" id="overview">')
script='''
const M=D.mentor,MS=D.steps.find(s=>s.number===22),msection=name=>MS.sections.find(s=>s.name===name);
$('mpop').textContent=fmt(M.population);$('mapps').textContent=fmt(M.stages.applied);$('mhires').textContent=fmt(M.stages.onboarded);$('mevents').textContent=fmt(M.files.event.rows);
const mainStages=['searched','screened','applied','shortlisted','assessed','interviewed','selected','offered','accepted','onboarded'];
$('mfunnel').innerHTML=mainStages.map(st=>`<div style="display:grid;grid-template-columns:105px 1fr 85px;gap:10px;align-items:center;margin:11px 0"><span>${esc(st)}</span><span style="background:#eaf0f7;border-radius:3px;height:16px"><span style="display:block;border-radius:3px;height:16px;background:#345f96;width:${Math.max(.7,M.stages[st]/M.population*100)}%"></span></span><b style="text-align:right;font-variant-numeric:tabular-nums">${fmt(M.stages[st])}</b></div>`).join('');
$('mbranches').textContent='Decision branches: '+fmt(M.stages.rejected)+' employer rejections; '+fmt(M.stages.offer_declined)+' candidate offer declines. Non-progressed journeys remain at their last observed stage.';
$('mgig').innerHTML=grid(['Synthetic gig measure','Records'],[['Applications',50000],['Requests',10000],['Accepted / assigned',M.gig.accepted],['Rejected',M.gig.rejected],['Pending',M.gig.pending],['Externally completed',M.gig.completed],['Handoff retry pending',M.gig.handoff_retry_pending],['Completed with requester rating',M.gig.rated]]);
$('mmapping').textContent=D.contracts_count+' source contracts and '+D.mapping_count+' field mappings, including 5 new synthetic file contracts and '+D.mentor_mapping_rows.length+' new owned field mappings.';
for(const [id,name] of [['mtaxonomy','Job taxonomy'],['mkpis','Business KPI register'],['mgaps','Native schema gap register'],['mtests','Mentor negative test evidence']]){const s=msection(name);const rows=s.rows.map(r=>r.map((v,i)=>id==='mkpis'&&i===5?(r[6]==='ratio'?(Number(v)*100).toFixed(1)+'%':fmt(v)):id==='mtaxonomy'&&i===4?(Number(v)*100).toFixed(0)+'%':v));$(id).innerHTML=grid(s.columns,rows)}
const actorSection=msection('Actor workflows'),actors=[...new Set(actorSection.rows.map(r=>r[1]))];$('mactor').innerHTML=actors.map(a=>'<option>'+esc(a)+'</option>').join('');$('mactor').value='Candidate';
function actorWorkflows(){$('mworkflows').innerHTML=grid(actorSection.columns,actorSection.rows.filter(r=>r[1]===$('mactor').value))}$('mactor').onchange=actorWorkflows;actorWorkflows();
$('mfiles').innerHTML='<table><thead><tr><th>File</th><th>Rows</th><th>Compressed bytes</th><th>SHA256</th></tr></thead><tbody>'+Object.entries(M.files).map(([k,v])=>`<tr><td><a href="scenario_data/${esc(v.file)}" download>${esc(v.file)}</a></td><td class="num">${fmt(v.rows)}</td><td class="num">${fmt(v.bytes)}</td><td class="small">${esc(v.sha256)}</td></tr>`).join('')+'</tbody></table>';
$('mentoroutputs').onclick=()=>openStep(22);nav('business');
'''
source=source.replace('</script></body></html>',script+'</script></body></html>')
(ROOT/'work/dashboard_v6.html').write_text(source,encoding='utf-8')
print('Prepared mentor business scenario UI')
